            + request.businessDay() + "|" + canonicalChannels(request.channelIds()) + "|" + startMs + "|" + endMs);
    return idempotent(request.requestId(), OP_REGISTER_WINDOW, hash, SponsorWindowResponse.class, () -> {
        List<String> channels = validateWindowScope(request.businessDay(), request.channelIds(), startMs, endMs);
        lockChannels(channels);
        if (repo.findLatestWindowByKey(windowKey).isPresent()) {
            throw ApiException.conflict("DUPLICATE_WINDOW_KEY", "排他窗键已存在: " + windowKey);
        }
        checkWindowOverlap(request.sponsorKey(), request.businessDay(), channels, startMs, endMs, null);
        checkWindowOccupancy(request.sponsorKey(), channels, request.businessDay(), startMs, endMs);
        long now = nowMs();
        long id = repo.insertSponsorWindow(windowKey, request.sponsorKey(), request.businessDay(), startMs, endMs, 1L, "ACTIVE", now);
        for (String c : channels) repo.insertSponsorWindowChannel(id, c);
        return new SponsorWindowResponse(windowKey, request.sponsorKey(), request.businessDay().toString(), channels, atMs(startMs), atMs(endMs), 1L, SponsorWindowStatus.ACTIVE, atMs(now));
    });
}
